export const getParseImportFileUrl = (projectId: number,) => {




  return `/api/projects/${projectId}/import/parse`
}

/**
 * @summary Upload and parse an Excel or CSV file, returns sheet/column preview
 */
export const parseImportFile = async (projectId: number,
    importFileForm: ImportFileForm, options?: RequestInit): Promise<ParseResult> => {
    const formData = new FormData();
formData.append(`file`, importFileForm.file);
if(importFileForm.csvClassName !== undefined) {
 formData.append(`csvClassName`, importFileForm.csvClassName);
 }

  return customFetch<ParseResult>(getParseImportFileUrl(projectId),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





